{
  "title": "Run One-on-Ones That Actually Matter",
  "seriesTag": "New Manager Playbook",
  "brand": {
    "apply": false,
    "paper": "#EFE9DA",
    "ink": "#212B21",
    "accent": "#C08A28",
    "headline": "editorial",
    "body": "clean"
  },
  "slides": [
    {
      "title": "Your One-on-Ones Are Probably Status Meetings in Disguise",
      "body": "If your team member spends the whole time telling you what they worked on this week, the meeting isn't serving either of you. Here's how to fix that.",
      "isCover": true
    },
    {
      "title": "The One-on-One Is Their Meeting, Not Yours",
      "body": "Your job is to show up, listen, and remove obstacles. The agenda should be driven by them — not your task list or project updates.",
      "isCover": false
    },
    {
      "title": "Ban the Status Update (You Have Tools for That)",
      "body": "Slack, Asana, Jira, email — use them. Status belongs in async tools. The one-on-one is for things that are hard to say in writing.",
      "isCover": false
    },
    {
      "title": "Ask Questions That Open the Room",
      "body": "Try: 'What's feeling hard right now?' or 'Is there anything slowing you down that I can help clear?' These invite honesty, not performance.",
      "isCover": false
    },
    {
      "title": "Make It a Space for Growth, Not Just Problems",
      "body": "Ask about what they're learning, what they want to get better at, and where they want to go. People stay where they feel seen.",
      "isCover": false
    },
    {
      "title": "Take Notes and Follow Through Every Time",
      "body": "Nothing kills trust faster than forgetting what was said last week. A simple running doc shared between both of you works perfectly.",
      "isCover": false
    },
    {
      "title": "Save This and Run a Better One-on-One This Week",
      "body": "Pick one question from slide 4, open your next one-on-one with it, and let them lead. That's the whole shift.",
      "isCover": true
    }
  ]
}

{
  "title": "Onboarding Your First Operations Hire",
  "seriesTag": "Ops Foundations",
  "brand": {
    "apply": true,
    "paper": "#0A1628",
    "ink": "#F5F0E8",
    "accent": "#AAFF00",
    "headline": "editorial",
    "body": "clean"
  },
  "slides": [
    {
      "title": "Your First Ops Hire Will Make or Break Your Systems",
      "body": "Most founders celebrate the hire — then hand them a mess. Here's how to set them up so they actually fix it.",
      "isCover": true
    },
    {
      "title": "Before Day One, Document What Exists",
      "body": "Write down every recurring task, tool, and process — even rough ones. Your new hire can't improve what they can't see.",
      "isCover": false
    },
    {
      "title": "Give Them a 30-Day Listening Window",
      "body": "Resist the urge to hand them a to-do list immediately. Let them observe, ask questions, and map the real workflow first.",
      "isCover": false
    },
    {
      "title": "Assign One Ownership Area Right Away",
      "body": "Pick a single process — invoicing, scheduling, vendor comms — and make it fully theirs. Clear ownership builds confidence fast.",
      "isCover": false
    },
    {
      "title": "Schedule a Weekly Ops Sync From Week One",
      "body": "A standing 30-minute check-in creates space for blockers, questions, and alignment before small issues compound.",
      "isCover": false
    },
    {
      "title": "Set a 90-Day Review Milestone",
      "body": "Agree on two or three measurable outcomes by day 90. It removes ambiguity and gives both sides a shared definition of success.",
      "isCover": false
    },
    {
      "title": "Save This Before You Make That Hire",
      "body": "Come back to this when you're ready to bring your first ops person on board. The right start saves months of cleanup.",
      "isCover": true
    }
  ]
}

{
  "title": "You Don't Need 4 Hours to Do Deep Work",
  "seriesTag": "Myth Busted",
  "brand": {
    "apply": false,
    "paper": "#EFE9DA",
    "ink": "#212B21",
    "accent": "#C08A28",
    "headline": "editorial",
    "body": "clean"
  },
  "slides": [
    {
      "title": "You Don't Need a 4-Hour Block to Do Deep Work",
      "body": "Most knowledge workers believe deep work is impossible without a long, uninterrupted stretch of time. That belief is costing you more than you think.",
      "isCover": true
    },
    {
      "title": "The Myth",
      "body": "\"If I can't protect four hours, there's no point starting.\" This all-or-nothing thinking leads to postponing your most important work indefinitely.",
      "isCover": false
    },
    {
      "title": "What the Research Actually Shows",
      "body": "Cal Newport and cognitive scientists agree: most people can sustain true focus for only 60–90 minutes before mental fatigue sets in. Four hours is rarely real deep work anyway.",
      "isCover": false
    },
    {
      "title": "Quality of Attention Beats Duration",
      "body": "A sharp, distraction-free 45 minutes produces more meaningful output than a drifting three-hour session filled with micro-interruptions and tab-switching.",
      "isCover": false
    },
    {
      "title": "The \"Minimum Viable Block\" Approach",
      "body": "Identify the smallest block that lets you enter a focused state — often just 25–50 minutes. Stack two or three of these across a day and you've built a deep work practice.",
      "isCover": false
    },
    {
      "title": "Protect the Entry, Not Just the Clock",
      "body": "The real bottleneck isn't length — it's the transition into focus. Reduce startup friction with a ritual: close notifications, set an intention, and begin the same way every time.",
      "isCover": false
    },
    {
      "title": "Save This and Rethink Your Deep Work Schedule",
      "body": "Stop waiting for the perfect four-hour window. Start with the block you actually have — and use it with full intention.",
      "isCover": true
    }
  ]
}

